function DetailDrawer({job,threshold,onClose}){if(!job)return null;return<><button className="fixed inset-0 z-50 bg-slate-950/25" onClick={onClose} aria-label="Inchide detaliile"/><aside className="fixed inset-y-0 right-0 z-[60] w-full max-w-xl overflow-y-auto border-l border-slate-200 bg-white shadow-2xl"><div className="sticky top-0 flex items-center justify-between border-b border-slate-100 bg-white px-6 py-4"><div className="text-xs font-semibold uppercase tracking-wide text-slate-400">Detalii job</div><button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-lg hover:bg-slate-100"><Icon name="close"/></button></div><div className="space-y-6 p-6"><div><h2 className="font-display text-2xl font-bold text-slate-950">{job.title}</h2><p className="mt-1 text-sm text-slate-500">{job.company}</p></div><div className="grid grid-cols-2 gap-3"><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">FIT</div><div className="mt-1"><FitBadge fit={job.fit} threshold={threshold}/></div></div><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Mod lucru</div><div className="mt-1"><ModeBadge mode={job.mode}/></div></div><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Locatie</div><div className="mt-1 text-sm font-medium text-slate-700">{job.location}</div></div><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Tara / tari</div><div className="mt-1 text-sm font-medium text-slate-700">{job.countries?.length?job.countries.join(', '):'Nespecificat'}</div></div><div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Sursa</div><div className="mt-1 text-sm font-medium text-slate-700">{job.source}</div></div>{job.remote&&<div className="rounded-xl bg-slate-50 p-3"><div className="text-xs text-slate-400">Scope Remote</div><div className="mt-1 text-sm font-medium text-slate-700">{job.remoteScope}</div></div>}</div>{job.pros?.length>0&&<div><h3 className="text-sm font-semibold text-slate-900">Puncte forte</h3><ul className="mt-2 space-y-2 text-sm text-slate-600">{job.pros.map((x,i)=><li key={i}>• {x}</li>)}</ul></div>}{job.risks?.length>0&&<div><h3 className="text-sm font-semibold text-slate-900">Riscuri</h3><ul className="mt-2 space-y-2 text-sm text-slate-600">{job.risks.map((x,i)=><li key={i}>• {x}</li>)}</ul></div>}<div><h3 className="text-sm font-semibold text-slate-900">Descriere</h3><div className="mt-2 whitespace-pre-wrap text-sm leading-6 text-slate-600">{job.description||'Descriere indisponibila.'}</div></div>{job.url&&<a href={job.url} target="_blank" rel="noopener noreferrer" className="inline-flex h-10 items-center gap-2 rounded-xl bg-blue-600 px-4 text-sm font-semibold text-white">Deschide jobul <Icon name="external"/></a>}</div></aside></>;}

function CriteriaCard({title,note,children,className}){return<section className={cx('rounded-2xl border border-slate-200 bg-white p-4 shadow-sm',className)}><h2 className="font-display text-base font-bold text-slate-900">{title}</h2>{note&&<p className="mt-1 text-sm text-slate-500">{note}</p>}<div className="mt-3 space-y-3">{children}</div></section>;}
function CheckRow({checked,onChange,children,disabled=false}){return<label className={cx('flex items-start gap-3 text-sm text-slate-700',disabled?'cursor-not-allowed opacity-60':'cursor-pointer')}><input type="checkbox" checked={checked} onChange={e=>onChange(e.target.checked)} disabled={disabled} className="mt-0.5 h-4 w-4 rounded border-slate-300"/><span>{children}</span></label>;}
function ChipsSelector({label,values,onChange,options,placeholder}){const available=options.filter(([value])=>!values.includes(value));return<div><div className="text-sm text-slate-700">{label}</div><select defaultValue="" onChange={e=>{if(e.target.value)onChange([...values,e.target.value]);e.target.value='';}} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700"><option value="">{placeholder}</option>{available.map(([value,text])=><option key={value} value={value}>{text}</option>)}</select><div className="mt-2 flex flex-wrap gap-2">{values.map(value=><button type="button" key={value} onClick={()=>onChange(values.filter(x=>x!==value))} className="inline-flex items-center gap-1 rounded-full bg-slate-100 px-2.5 py-1 text-xs font-medium text-slate-600">{COUNTRY_NAMES[value]||value}<Icon name="close" className="h-3 w-3"/></button>)}</div></div>;}
function RegionSelector({label,values,onChange}){return<div><div className="text-sm text-slate-700">{label}</div><div className="mt-2 flex flex-wrap gap-2">{REGION_OPTIONS.map(region=><button type="button" key={region} onClick={()=>onChange(values.includes(region)?values.filter(x=>x!==region):[...values,region])} className={cx('rounded-full border px-3 py-1.5 text-xs font-semibold',values.includes(region)?'border-blue-200 bg-blue-50 text-blue-700':'border-slate-200 bg-white text-slate-600')}>{region==='ASIA'?'Asia':region}</button>)}</div></div>;}
function CriteriaPage({draft,setDraft,saved,onSave,saving}){const dirty=JSON.stringify(draft)!==JSON.stringify(saved),update=(key,value)=>setDraft(v=>({...v,[key]:value}));const addExclusion=value=>{if(value&&!draft.exclusions.includes(value))update('exclusions',[...draft.exclusions,value])},removeExclusion=value=>update('exclusions',draft.exclusions.filter(x=>x!==value));const conflict=geographyConflicts(draft),missingTarget=!hasTargetGeography(draft);return<div className="space-y-5"><div className="grid grid-cols-1 gap-5 md:grid-cols-2"><CriteriaCard title="Roluri urmarite"><CheckRow checked={draft.rolePm} onChange={v=>update('rolePm',v)}>Project Manager / IT Project Manager</CheckRow><CheckRow checked={draft.roleDelivery} onChange={v=>update('roleDelivery',v)}>Delivery / Technical Project Manager</CheckRow><CheckRow checked={draft.roleService} onChange={v=>update('roleService',v)}>Service Manager</CheckRow><CheckRow checked={draft.roleScrum} onChange={v=>update('roleScrum',v)}>Scrum Master</CheckRow><CheckRow checked={draft.roleProgram} onChange={v=>update('roleProgram',v)}>Program / PMO Manager</CheckRow></CriteriaCard><CriteriaCard title="Mod de lucru"><CheckRow checked={draft.workRemote} onChange={v=>update('workRemote',v)}>Remote</CheckRow><CheckRow checked={draft.workHybrid} onChange={v=>update('workHybrid',v)}>Hibrid</CheckRow></CriteriaCard><CriteriaCard title="Tara / regiune"><RegionSelector label="Regiuni incluse" values={draft.targetRegions} onChange={v=>update('targetRegions',v)}/><ChipsSelector label="Tari incluse" values={draft.targetCountries} onChange={v=>update('targetCountries',v)} options={COUNTRY_OPTIONS} placeholder="Adauga o tara"/></CriteriaCard><CriteriaCard title="Praguri"><label className="block text-sm text-slate-700">Vechime<select value={draft.freshness} onChange={e=>update('freshness',Number(e.target.value))} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 bg-white px-3"><option value={24}>24 ore</option><option value={36}>36 ore</option><option value={48}>48 ore</option><option value={120}>5 zile</option></select></label><label className="block text-sm text-slate-700">FIT ridicat<input type="number" min="50" max="100" value={draft.fitThreshold} onChange={e=>update('fitThreshold',Number(e.target.value))} className="mt-1.5 h-10 w-full rounded-xl border border-slate-200 px-3"/></label><CheckRow checked={draft.keepReposts} onChange={v=>update('keepReposts',v)}>Pastreaza repostarile</CheckRow></CriteriaCard><CriteriaCard title="Contract"><div className="flex items-center gap-2"><input type="number" value={draft.rateMin} onChange={e=>update('rateMin',Number(e.target.value))} className="h-10 w-28 rounded-xl border border-slate-200 px-3"/><span>—</span><input type="number" value={draft.rateMax} onChange={e=>update('rateMax',Number(e.target.value))} className="h-10 w-28 rounded-xl border border-slate-200 px-3"/><span className="text-xs text-slate-400">EUR/zi</span></div><CheckRow checked={draft.immediateStart} onChange={v=>update('immediateStart',v)}>Disponibilitate imediata</CheckRow></CriteriaCard><CriteriaCard title="JobsPipe" note="Ramane dezactivat in Pachetul 2."><select value={draft.jobspipeMode} disabled className="h-10 w-full rounded-xl border border-slate-200 bg-slate-50 px-3 text-sm"><option value="disabled">Oprit</option><option value="apify">Apify</option><option value="direct">Direct</option></select></CriteriaCard><CriteriaCard title="Excluderi" className="md:col-span-2"><div className="grid gap-4 md:grid-cols-2"><div><select defaultValue="" onChange={e=>{addExclusion(e.target.value);e.target.value='';}} className="h-10 w-full rounded-xl border border-slate-200 bg-white px-3 text-sm"><option value="">Adauga excludere</option>{EXCLUSION_SUGGESTIONS.map(x=><option key={x}>{x}</option>)}</select><div className="mt-2 flex flex-wrap gap-2">{draft.exclusions.map(x=><button key={x} onClick={()=>removeExclusion(x)} className="rounded-full bg-slate-100 px-2.5 py-1 text-xs">{x} ×</button>)}</div></div><div className="space-y-3"><RegionSelector label="Regiuni excluse" values={draft.excludedRegions} onChange={v=>update('excludedRegions',v)}/><ChipsSelector label="Tari excluse" values={draft.excludedCountries} onChange={v=>update('excludedCountries',v)} options={COUNTRY_OPTIONS} placeholder="Adauga tara exclusa"/></div></div>{missingTarget&&<div className="mt-3 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">Selecteaza cel putin o tara sau regiune tinta.</div>}{conflict&&<div className="mt-3 rounded-xl border border-red-200 bg-red-50 px-3 py-2 text-sm text-red-700">Exista conflict intre includeri si excluderi.</div>}</CriteriaCard></div><div className="flex items-center justify-between rounded-2xl border border-slate-200 bg-white px-5 py-4 shadow-sm"><span className={cx('text-sm font-medium',dirty?'text-amber-600':'text-slate-500')}>{dirty?'Modificari nesalvate':'Preferinte salvate'}</span><button onClick={onSave} disabled={!dirty||saving||conflict||missingTarget} className="h-10 rounded-xl border border-slate-300 bg-white px-4 text-sm font-semibold disabled:opacity-50">{saving?'Se salveaza...':'Salveaza preferintele'}</button></div></div>;}

function App(){
  const[clientId,setClientId]=useState(null),[auth,setAuth]=useState({status:'signed-out',token:null,email:null,error:null}),[dataState,setDataState]=useState({status:'idle',error:null});
  const[jobs,setJobs]=useState([]),[applications,setApplications]=useState([]),[sources,setSources]=useState([]),[sourceCategories,setSourceCategories]=useState([]),[runStatus,setRunStatus]=useState(null),[runHistory,setRunHistory]=useState([]),[canonicalConfig,setCanonicalConfig]=useState(null);
  const[savedCriteria,setSavedCriteria]=useState(criteriaFromConfig({})),[draftCriteria,setDraftCriteria]=useState(criteriaFromConfig({})),[view,setView]=useState('jobs');
  const[filters,setFilters]=useState({search:'',quick:'all',freshness:24,workModes:[...ALL_WORK_MODES],sort:'fit-desc'}),[kpiFilter,setKpiFilter]=useState('all'),[detailJob,setDetailJob]=useState(null),[running,setRunning]=useState(false),[saving,setSaving]=useState(false),[toast,setToast]=useState(null);
  const[archivedKeys,setArchivedKeys]=useState(()=>{try{return JSON.parse(localStorage.getItem('archivedJobKeys')||'[]')}catch{return[]}});
  const pollGenerationRef=useRef(0);
  const notify=useCallback((message,type='info')=>{const id=Date.now();setToast({id,message,type});window.setTimeout(()=>setToast(current=>current?.id===id?null:current),3500);},[]);

  useEffect(()=>{commandApi('/auth/config',null).then(config=>{if(!config?.configured||!config?.client_id)throw new Error('Autentificarea Google nu este configurata complet.');setClientId(config.client_id);}).catch(error=>setAuth(current=>({...current,error:error.message})));},[]);
  useEffect(()=>()=>{pollGenerationRef.current+=1;},[]);

  const clearData=useCallback(()=>{setJobs([]);setApplications([]);setSources([]);setSourceCategories([]);setRunStatus(null);setRunHistory([]);setCanonicalConfig(null);},[]);
  const loadData=useCallback(async token=>{setDataState({status:'loading',error:null});try{
    const[jobPayload,statusPayload,historyPayload,applicationPayload,sourcePayload,categoryPayload,configPayload]=await Promise.all([
      fetchJson('/data/jobs.json',token),fetchJson('/data/run-status.json',token),fetchJson('/data/run-history.json',token),fetchJson('/data/applications.json',token),fetchJson('/data/sources.json',token),fetchJson('/data/source-categories.json',token),fetchJson('/data/search-config.json',token),
    ]);
    for(const [payload,name] of [[jobPayload,'jobs.json'],[statusPayload,'run-status.json'],[historyPayload,'run-history.json'],[applicationPayload,'applications.json'],[sourcePayload,'sources.json'],[categoryPayload,'source-categories.json'],[configPayload,'search-config.json']]) validateContract(payload,name);
    const criteria=criteriaFromConfig(configPayload);
    setJobs((jobPayload.jobs||[]).map(normalizeJob));setApplications((applicationPayload.applications||[]).map(normalizeApplication));setSources((sourcePayload.sources||[]).map(normalizeSource));setSourceCategories(categoryPayload.categories||[]);setRunStatus(statusPayload);setRunHistory(historyPayload.runs||[]);setCanonicalConfig(configPayload);setSavedCriteria(criteria);setDraftCriteria(criteria);setFilters(current=>({...current,freshness:criteria.freshness||24}));setDataState({status:'ready',error:null});return statusPayload;
  }catch(error){setDataState({status:'error',error});throw error;}},[]);

  const handleCredential=useCallback(async credential=>{setAuth({status:'authenticating',token:null,email:null,error:null});try{const session=await commandApi('/auth/session',credential,{method:'POST'});setAuth({status:'authenticated',token:credential,email:session?.email||null,error:null});try{await loadData(credential);notify('Autentificare Google reusita.','success');}catch(error){notify(`Autentificarea a reusit, dar datele nu s-au incarcat: ${error.message}`,'error');}}catch(error){const message=error.status===403?'Contul Google nu este autorizat pentru aceasta aplicatie.':`Autentificare esuata: ${error.message}`;setAuth({status:'signed-out',token:null,email:null,error:message});}},[loadData,notify]);
  const logout=useCallback(()=>{pollGenerationRef.current+=1;try{window.google?.accounts?.id?.disableAutoSelect();}catch{}setAuth({status:'signed-out',token:null,email:null,error:null});setDataState({status:'idle',error:null});clearData();setDetailJob(null);setRunning(false);notify('Contul Google a fost deconectat.','info');},[clearData,notify]);
  const retryData=useCallback(()=>{if(auth.token)loadData(auth.token).then(()=>notify('Datele au fost reincarcate.','success')).catch(error=>notify(`Incarcarea a esuat: ${error.message}`,'error'));},[auth.token,loadData,notify]);

  const activeJobs=useMemo(()=>jobs.filter(job=>!archivedKeys.includes(jobKey(job))),[jobs,archivedKeys]);
  const baseRows=useMemo(()=>view==='applications'?applications:view==='review'?activeJobs.filter(job=>job.status==='review'):activeJobs,[view,applications,activeJobs]);
  const threshold=savedCriteria.fitThreshold||80;
  const modeFreshRows=useMemo(()=>view==='applications'?baseRows:baseRows.filter(job=>ageHours(job.date_posted,job.age)<=filters.freshness&&filters.workModes.includes(job.mode)),[view,baseRows,filters.freshness,filters.workModes]);
  const filteredRows=useMemo(()=>{if(view==='applications')return[...baseRows];const q=filters.search.trim().toLowerCase();const rows=modeFreshRows.filter(job=>{const quick=filters.quick==='all'||(filters.quick==='high'&&job.fit!==null&&job.fit>=threshold)||(filters.quick==='b2b'&&job.b2b);const kpi=kpiFilter==='all'||(kpiFilter==='new'&&ageHours(job.date_posted,job.age)<=24)||(kpiFilter==='high'&&job.fit!==null&&job.fit>=threshold)||(kpiFilter==='repost'&&job.repost)||(kpiFilter==='remote'&&job.mode==='Remote');const text=`${job.title} ${job.company} ${job.description} ${job.source} ${job.location} ${(job.countries||[]).join(' ')}`.toLowerCase();return quick&&kpi&&(!q||text.includes(q));});return[...rows].sort(filters.sort==='fit-asc'?(a,b)=>(a.fit??Number.MAX_SAFE_INTEGER)-(b.fit??Number.MAX_SAFE_INTEGER)||a.age-b.age:(a,b)=>(b.fit??-1)-(a.fit??-1)||a.age-b.age);},[view,baseRows,modeFreshRows,filters.quick,filters.search,filters.sort,threshold,kpiFilter]);
  const quickCounts=useMemo(()=>({all:modeFreshRows.length,high:modeFreshRows.filter(j=>j.fit!==null&&j.fit>=threshold).length,b2b:modeFreshRows.filter(j=>j.b2b).length}),[modeFreshRows,threshold]);
  const dashboardJobs=useMemo(()=>activeJobs.filter(job=>filters.workModes.includes(job.mode)),[activeJobs,filters.workModes]);
  const metrics=useMemo(()=>({jobs:dashboardJobs.filter(j=>ageHours(j.date_posted,j.age)<=24).length,high:dashboardJobs.filter(j=>j.fit>=threshold).length,reposts:dashboardJobs.filter(j=>j.repost).length,remote:dashboardJobs.filter(j=>j.mode==='Remote').length,threshold}),[dashboardJobs,threshold]);
  const counts=useMemo(()=>({jobs:activeJobs.length,review:activeJobs.filter(j=>j.status==='review').length,applications:applications.length}),[activeJobs,applications]);
  const archiveJob=job=>{const next=[...new Set([...archivedKeys,jobKey(job)])];setArchivedKeys(next);localStorage.setItem('archivedJobKeys',JSON.stringify(next));notify('Job arhivat local.','info');};

  const pollRun=useCallback(async(previousRunId,previousCompletedAt)=>{const generation=++pollGenerationRef.current;const baseline={runId:previousRunId??null,completedAt:previousCompletedAt??null};for(let attempt=0;generation===pollGenerationRef.current;attempt+=1){await new Promise(resolve=>setTimeout(resolve,pollingDelayMs(attempt)));if(generation!==pollGenerationRef.current)return null;try{const status=await fetchJson(`/data/run-status.json?t=${Date.now()}`,auth.token);setRunStatus(status);if(!terminalForBaseline(status,baseline))continue;await loadData(auth.token);const notice=completionNotice(status);notify(notice.message,notice.type);return status;}catch(error){if(error?.status===401||error?.status===403){notify('Urmarirea rularii s-a oprit deoarece sesiunea nu mai este autorizata.','error');return null;}}}return null;},[auth.token,loadData,notify]);
  useEffect(()=>{if(auth.status!=='authenticated'||!auth.token||dataState.status!=='ready'||running||!isActiveRunStatus(runStatus?.status))return undefined;setRunning(true);pollRun(runStatus?.run_id??null,runStatus?.completed_at??null).finally(()=>setRunning(false));return undefined;},[auth.status,auth.token,dataState.status,runStatus?.status,runStatus?.run_id,runStatus?.completed_at,running,pollRun]);

  const runSearch=useCallback(async()=>{if(!auth.token||running)return;if(geographyConflicts(draftCriteria)){notify('Rezolva conflictul dintre includerile si excluderile teritoriale.','error');return;}if(!hasTargetGeography(draftCriteria)){notify('Selecteaza cel putin o tara sau regiune tinta.','error');return;}setRunning(true);const previousRunId=runStatus?.run_id||null,previousCompletedAt=runStatus?.completed_at||null;try{await commandApi('/commands/run',auth.token,{method:'POST',body:JSON.stringify(draftCriteria)});setSavedCriteria(draftCriteria);notify('Verificarea manuala a fost pornita.','info');await pollRun(previousRunId,previousCompletedAt);}catch(error){if(error.status===409){notify('Exista deja o verificare in curs.','info');await pollRun(previousRunId,previousCompletedAt);}else notify(`Nu am putut porni verificarea: ${error.message}`,'error');}finally{setRunning(false);}},[auth.token,running,runStatus,draftCriteria,notify,pollRun]);
  const saveCriteria=useCallback(async()=>{if(!auth.token||saving)return;if(geographyConflicts(draftCriteria)){notify('Rezolva conflictul dintre includerile si excluderile teritoriale.','error');return;}if(!hasTargetGeography(draftCriteria)){notify('Selecteaza cel putin o tara sau regiune tinta.','error');return;}setSaving(true);try{await commandApi('/config',auth.token,{method:'PUT',body:JSON.stringify(draftCriteria)});setSavedCriteria(draftCriteria);setCanonicalConfig(current=>current?{...current,freshness_hours:draftCriteria.freshness,fit_threshold:draftCriteria.fitThreshold,target_regions:draftCriteria.targetRegions,target_country_codes:draftCriteria.targetCountries,search_country_codes:draftCriteria.targetCountries,excluded_regions:draftCriteria.excludedRegions,excluded_country_codes:draftCriteria.excludedCountries}:current);setFilters(current=>({...current,freshness:draftCriteria.freshness}));notify('Preferintele au fost salvate. Cautarea nu a fost pornita.','success');}catch(error){notify(`Preferintele nu au putut fi salvate: ${error.message}`,'error');}finally{setSaving(false);}},[auth.token,saving,draftCriteria,notify]);

  if(auth.status!=='authenticated')return<><SignedOutScreen clientId={clientId} authError={auth.error} authStatus={auth.status} onCredential={handleCredential}/><Toast toast={toast}/></>;
  return<div className="min-h-screen bg-slate-50 md:flex"><Sidebar view={view} onView={v=>{setView(v);if(v!=='jobs')setKpiFilter('all');}} counts={counts} runStatus={runStatus}/><main className="min-w-0 flex-1"><div className="mx-auto w-full max-w-[1400px] space-y-5 px-4 py-5 sm:px-6 lg:px-8 lg:py-7"><Header view={view} email={auth.email} running={running} onRun={runSearch} onLogout={logout}/>{dataState.status==='loading'&&<LoadingPanel/>}{dataState.status==='error'&&<ErrorPanel error={dataState.error} onRetry={retryData}/>} {dataState.status==='ready'&&<>{view==='jobs'&&<KPIGrid metrics={metrics} selected={kpiFilter} onSelect={setKpiFilter}/>} {(view==='jobs'||view==='review')&&<Filters filters={filters} setFilters={setFilters} counts={quickCounts} defaultFreshness={savedCriteria.freshness} onResetKpi={()=>setKpiFilter('all')}/>} {(view==='jobs'||view==='review'||view==='applications')&&<JobTable rows={filteredRows} threshold={threshold} onDetails={setDetailJob} onArchive={archiveJob}/>} {view==='criteria'&&<CriteriaPage draft={draftCriteria} setDraft={setDraftCriteria} saved={savedCriteria} onSave={saveCriteria} saving={saving}/>} {view==='admin'&&<AdminShell sources={sources} setSources={setSources} sourceCategories={sourceCategories} setSourceCategories={setSourceCategories} runStatus={runStatus} runHistory={runHistory} running={running} onRun={runSearch} notify={notify} token={auth.token}/>}</>}</div></main><DetailDrawer job={detailJob} threshold={threshold} onClose={()=>setDetailJob(null)}/><Toast toast={toast}/></div>;
}

createRoot(document.getElementById('root')).render(<React.StrictMode><App/></React.StrictMode>);
